// Builds the browser daemon that runs inside cloud sandboxes: the shared
// BrowserController plus a tiny localhost HTTP server, as one .ts file that
// Node runs directly with type stripping. Output is committed.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const controller = readFileSync(join(here, '../src/browser/controller.ts'), 'utf8');
const server = `
// ---- daemon (generated by scripts/gen-daemon.mjs) ----
import { chromium, selectors } from 'playwright';
import http from 'node:http';
import { randomBytes, timingSafeEqual } from 'node:crypto';
import { renameSync, writeFileSync } from 'node:fs';

const home = process.env.HOME || '/tmp';
// Only Wren's own requests are served (W-169). Pages in this browser can send requests to
// 127.0.0.1 too: whatever a browser sends carries an Origin or Sec-Fetch-* header, or comes
// with another Host (DNS rebinding), and none of it can know this token. A new one is made at
// every start, in a file only commands Wren runs on this VM read (curl -H @file, so it's never
// on a command line).
const token = randomBytes(32).toString('hex');
writeFileSync(home + '/.wren/browser.token.tmp', 'x-wren-token: ' + token + '\\n', { mode: 0o600 });
renameSync(home + '/.wren/browser.token.tmp', home + '/.wren/browser.token');
const expected = Buffer.from(token);
await registerSelectors(selectors);
const context = await chromium.launchPersistentContext(home + '/.wren/profile', {
  headless: true,
  viewport: { width: 1280, height: 800 },
  args: ['--no-sandbox', '--disable-dev-shm-usage'],
  userAgent: 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0 Safari/537.36 WrenAgent',
});
const controller = new BrowserController(context);
const ACTIONS = new Set(['navigate', 'snapshot', 'click', 'type', 'press', 'scroll', 'screenshot', 'back', 'describe', 'close']);
const MAX_BODY = 1024 * 1024;
const MAX_WAITING = 8;
const text = (v: unknown, max: number) => v === undefined || (typeof v === 'string' && v.length <= max);
const flag = (v: unknown) => v === undefined || typeof v === 'boolean';
function valid(a: any): boolean {
  if (!a || typeof a !== 'object' || Array.isArray(a) || !ACTIONS.has(a.action)) return false;
  // Every request is a task's ("close" without a tab would close the whole browser).
  if (typeof a.tab !== 'string' || !a.tab || a.tab.length > 100) return false;
  if (a.expect !== undefined && (!a.expect || typeof a.expect !== 'object' || Object.values(a.expect).some((v) => !text(v, 4000)))) return false;
  return text(a.url, 8192) && text(a.ref, 100) && text(a.text, 100000) && text(a.key, 100) && text(a.direction, 10) && flag(a.submit) && flag(a.full_page) && (a.amount === undefined || typeof a.amount === 'number');
}
const refuse = (res: http.ServerResponse, status: number) => {
  res.statusCode = status;
  res.setHeader('connection', 'close');
  res.end();
};
let waiting = 0;
let queue: Promise<unknown> = Promise.resolve();
const server = http.createServer((req, res) => {
  if (req.headers.origin !== undefined || Object.keys(req.headers).some((h) => h.startsWith('sec-fetch-'))) return refuse(res, 403);
  if (req.headers.host !== '127.0.0.1:9333') return refuse(res, 403);
  if (req.url === '/health') { res.end('ok'); return; }
  if (req.method !== 'POST' || req.url !== '/act') return refuse(res, 404);
  const given = Buffer.from(String(req.headers['x-wren-token'] ?? ''));
  if (given.length !== expected.length || !timingSafeEqual(given, expected)) return refuse(res, 401);
  if (req.headers['content-type'] !== 'application/json') return refuse(res, 415);
  if (waiting >= MAX_WAITING) return refuse(res, 503);
  waiting++;
  let left = true;
  const leave = () => { if (left) { left = false; waiting--; } };
  let body = '';
  let size = 0;
  req.setEncoding('utf8');
  req.on('data', (c: string) => {
    size += Buffer.byteLength(c);
    if (size <= MAX_BODY) body += c;
    else if (left) { leave(); refuse(res, 413); req.destroy(); }
  });
  req.on('close', () => { if (!req.complete) leave(); });
  req.on('end', () => {
    if (!left) return;
    let a: any;
    try { a = JSON.parse(body); } catch { a = undefined; }
    if (!valid(a)) { leave(); return refuse(res, 400); }
    queue = queue.then(async () => {
      let out;
      try { out = await controller.act(a); } catch (e) { out = { ok: false, error: String((e as Error).message) }; }
      leave();
      res.setHeader('content-type', 'application/json');
      res.end(JSON.stringify(out));
    });
  });
});
// Receiving a request has a time limit; acting on it doesn't.
server.requestTimeout = 15000;
server.headersTimeout = 10000;
server.listen(9333, '127.0.0.1');
`;
const src = controller + server;
writeFileSync(join(here, '../src/browser/daemon-source.ts'), `// Generated by scripts/gen-daemon.mjs - do not edit.\nexport const BROWSER_DAEMON_TS = ${JSON.stringify(src)};\n`);
console.log('wrote daemon-source.ts', src.length, 'chars');
